```javascript
// 1. 获取工程内所有板子
const boards = await eda.dmt_Board.getAllBoardsInfo();

// 2. 输出每块板子的名称与下属文档
boards.forEach((board, i) => {
  console.log(`board[${i}]:`, board.name, 'schematic:', board.schematic?.uuid, 'pcb:', board.pcb?.uuid);
});

console.log('total:', boards.length);
```
